INSERT INTO `training_plans` VALUES (1,1,1,'新手增肌计划 - 全身训练','每周3天训练，采用全身训练方式','【训练分化方式】全身训练\n【训练频率】每周3天\n\n═══ 第1天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 高位下拉 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 杠铃推举 - 3组 x 8-12次\n5. 俄罗斯转体 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n═══ 第2天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 坐姿划船 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 哑铃推举 - 3组 x 8-12次\n5. 悬垂举腿 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n═══ 第3天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 高位下拉 - 4-5组 x 8-12次\n3. 腿举 - 4-5组 x 8-12次\n4. 杠铃推举 - 3组 x 8-12次\n5. 悬垂举腿 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n\n\n【周期化建议】\n第1-2周：适应期，60-70% 1RM\n第3-4周：力量期，75-80% 1RM\n第5-6周：增肌期，增加组数\n第7-8周：恢复周，减少容量30%\n\n【营养建议】热量盈余+300-500卡/天，蛋白质2.0-2.5g/kg体重','增肌','新手','',3,'标准','健身房',0,1,1766844866869,1766844866869),(2,3,4,'高级增肌计划 - 全身训练','每周3天训练，采用全身训练方式','【训练分化方式】全身训练\n【训练频率】每周3天\n\n═══ 第1天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 高位下拉 - 4-5组 x 8-12次\n3. 腿举 - 4-5组 x 8-12次\n4. 杠铃推举 - 3组 x 8-12次\n5. 悬垂举腿 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n═══ 第2天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 高位下拉 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 哑铃推举 - 3组 x 8-12次\n5. 俄罗斯转体 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n═══ 第3天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 坐姿划船 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 哑铃推举 - 3组 x 8-12次\n5. 悬垂举腿 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n\n\n【周期化建议】\n第1-2周：适应期，60-70% 1RM\n第3-4周：力量期，75-80% 1RM\n第5-6周：增肌期，增加组数\n第7-8周：恢复周，减少容量30%\n\n【营养建议】热量盈余+300-500卡/天，蛋白质2.0-2.5g/kg体重','增肌','高级','',3,'标准','健身房',1,1,1766853399133,1766853399133),(3,3,2,'新手增肌计划 - 全身训练','每周3天训练，采用全身训练方式','【训练分化方式】全身训练\n【训练频率】每周3天\n\n═══ 第1天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 高位下拉 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 杠铃推举 - 3组 x 8-12次\n5. 俄罗斯转体 - 3组 x 30-60秒\n\n组间休息：60-90秒\n────────────────────\n\n═══ 第2天：全身训练 ═══\n\n1. 杠铃卧推 - 4-5组 x 8-12次\n2. 坐姿划船 - 4-5组 x 8-12次\n3. 杠铃深蹲 - 4-5组 x 8-12次\n4. 杠铃推举 - 3组 x 8-12次\n5. 俄罗斯转体 - 3组 x 30-60秒\